package com.dbu.reservation.infrastructure.repository;
import com.dbu.reservation.domain.model.*;import com.dbu.reservation.domain.repository.UserRepository;import com.dbu.reservation.infrastructure.database.DatabaseConnection;import java.sql.*;import java.util.*;
public final class JdbcUserRepository implements UserRepository {
 public Optional<AuthenticatedUser> findForLogin(String universityId){String q="SELECT user_id,full_name,email,password_hash,role,account_status FROM users WHERE university_id=?";try(Connection c=DatabaseConnection.open();PreparedStatement p=c.prepareStatement(q)){p.setString(1,universityId);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();return Optional.of(new AuthenticatedUser(new User(r.getLong(1),r.getString(2),r.getString(3),Role.valueOf(r.getString(5)),r.getString(6)),r.getString(4)));}}catch(SQLException e){throw new IllegalStateException("Could not access users table.",e);}}
 public void register(String name,String universityId,String email,String phone,long dept,Role role,String hash){String q="INSERT INTO users(full_name,university_id,email,phone,department_id,password_hash,role,account_status) VALUES(?,?,?,?,?,?,?,'ACTIVE')";try(Connection c=DatabaseConnection.open();PreparedStatement p=c.prepareStatement(q)){p.setString(1,name.trim());p.setString(2,universityId.trim());p.setString(3,email.trim().toLowerCase());p.setString(4,phone);p.setLong(5,dept);p.setString(6,hash);p.setString(7,role.name());p.executeUpdate();}catch(SQLIntegrityConstraintViolationException e){throw new IllegalArgumentException("Email or university ID is already registered, or the selected department is invalid.");}catch(SQLException e){throw new IllegalStateException("Could not register user. Check the database connection and department selection.",e);}}
 public List<Department> departments(){String q="SELECT department_id,department_name FROM departments ORDER BY department_name";try(Connection c=DatabaseConnection.open();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){List<Department> departments=new ArrayList<>();while(r.next())departments.add(new Department(r.getLong(1),r.getString(2)));if(departments.isEmpty())throw new IllegalStateException("No departments are configured in the database.");return departments;}catch(SQLException e){throw new IllegalStateException("Could not load departments from the database.",e);}}
 public User getOrCreateGuest(){String lookup="SELECT user_id,full_name,email,role,account_status FROM users WHERE university_id='GUEST-SESSION'";try(Connection c=DatabaseConnection.open()){try(PreparedStatement p=c.prepareStatement(lookup);ResultSet r=p.executeQuery()){if(r.next())return new User(r.getLong(1),r.getString(2),r.getString(3),Role.valueOf(r.getString(4)),r.getString(5));}seedDefaultDepartmentsIfEmpty(c);long department;try(PreparedStatement p=c.prepareStatement("SELECT department_id FROM departments ORDER BY department_id LIMIT 1");ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalStateException("Could not initialize a department for the guest session.");department=r.getLong(1);}String insert="INSERT IGNORE INTO users(full_name,university_id,email,department_id,password_hash,role,account_status) VALUES('Guest Reservation User','GUEST-SESSION','guest@local.invalid',?,'NO_LOGIN','STUDENT','ACTIVE')";try(PreparedStatement p=c.prepareStatement(insert)){p.setLong(1,department);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement(lookup);ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalStateException("Could not create guest reservation account.");return new User(r.getLong(1),r.getString(2),r.getString(3),Role.valueOf(r.getString(4)),r.getString(5));}}catch(SQLException e){throw new IllegalStateException("Could not prepare the guest session; check the database connection and execute database/university_reservation.sql.",e);}}
 private void seedDefaultDepartmentsIfEmpty(Connection c)throws SQLException{try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM departments LIMIT 1");ResultSet r=check.executeQuery()){if(r.next())return;}try(PreparedStatement insert=c.prepareStatement("INSERT IGNORE INTO departments(department_name) VALUES(?),(?),(?),(?)")){insert.setString(1,"Computer Science");insert.setString(2,"Information Technology");insert.setString(3,"Electrical Engineering");insert.setString(4,"Registrar");insert.executeUpdate();}}
}
